#convert .py files in pythonDev/exudyn

def load_converter():
    project_root = Path(__file__).resolve().parent
    module_path = project_root / "src" / "pythonGenerator" / "autoGenerateDocstrings.py"
    if not module_path.exists():
        raise FileNotFoundError(f"Converter not found at {module_path}")
    spec = importlib.util.spec_from_file_location("autoGenerateDocstrings", module_path)
    mod = importlib.util.module_from_spec(spec)
    assert spec.loader is not None
    spec.loader.exec_module(mod)
    return mod.ConvertExuDoc2Docstrings

def TreeConvert2Temp(sourcePath: Path, destPath: Path):
    print('------- Exudyn: convert to docstrings -----------')
    
    #does not work here:
    #from src.pythonGenerator.autoGenerateDocstrings import ConvertExuDoc2Docstrings

    ConvertExuDoc2Docstrings=load_converter()
    
    # remove existing files->could contain invalid files!
    if destPath.exists() and 'tempExudyn' in str(destPath): #double check for destPath ...
        shutil.rmtree(destPath)

    shutil.copytree(sourcePath, destPath)

    for p in destPath.rglob("*.py"):
        if not (
                'GUI.py' in p.name
                or 'resultsMonitor.py' in p.name
                or '__init__.py' in p.name
                or 'itemInterface.py' in p.name
                ):
            #print('convert to docstrings in file: ', p.name)
            # txt = p.read_text(encoding="utf-8")
            # p.write_text(txt, encoding="utf-8")
            try:
                ConvertExuDoc2Docstrings(p, p)
            except:
                print('problem with Docstring:',p.name)

    print('------- Exudyn: convert to docstrings finished -----------')




