        print('------- Exudyn: BuildPy -----------')
        src_root = Path("pythonDev")
        build_cmd = self.get_finalized_command("build")
        
        tmp_root = Path(build_cmd.build_base) / 'tempExudyn' # tempfile.mkdtemp()
